import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { NotificationChannel, NotificationOrigin, NotificationCategory } from '@bk-dash/contracts-typescript/wire/enums'
import { BkdashNotification } from '../entities/BkdashNotification'
import { BkdashNotificationDelivery } from '../entities/BkdashNotificationDelivery'
import { BkdashNotificationRepository } from '../repositories/BkdashNotificationRepository'
import { BkdashNotificationDeliveryRepository } from '../repositories/BkdashNotificationDeliveryRepository'
import { NotificationSentEvent } from '../events'
import type { NotificationsDomainErrors } from '../errors'

export const SendNotificationInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid().optional(),
	targetUserIds: z.array(z.string()).optional(),
	title: z.string().min(1).max(200),
	content: z.string().min(1),
	category: z.enum(NotificationCategory),
	important: z.boolean().default(false),
	pushEnabled: z.boolean().default(true),
	emailEnabled: z.boolean().default(false),
	contentType: z.string().default('text/plain'),
	payload: z.record(z.string(), z.unknown()).optional(),
	scheduledAt: z.date().optional(),
})

export const SendNotificationOutputSchema = z.object({
	notificationId: z.uuid(),
	deliveriesCreated: z.number().int().min(0),
	deliveriesSkippedDuplicate: z.number().int().min(0),
})

/**
 * C53 SendNotification. Creates one BkdashNotification + N
 * BkdashNotificationDelivery rows (one per recipient × enabled channel).
 * Requires at least one targetUserId and at least one enabled channel.
 *
 * `scheduledAt` is accepted for SDK compatibility but not yet honored at
 * this layer — the scheduler integration that defers the persist to the
 * requested wall-clock lands in a follow-up iter; for now the rows are
 * created immediately with `deliveredAt = now`.
 */
@injectable()
export class SendNotification extends Handler<typeof SendNotificationInputSchema, typeof SendNotificationOutputSchema> {
	readonly name = 'send_notification' as const
	readonly inputSchema = SendNotificationInputSchema
	readonly outputSchema = SendNotificationOutputSchema

	constructor(
		private readonly notifications: BkdashNotificationRepository,
		private readonly deliveries: BkdashNotificationDeliveryRepository,
	) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const targets = input.targetUserIds ?? []
		if (targets.length === 0) {
			throw new BaseError<NotificationsDomainErrors>('EMPTY_RECIPIENTS')
		}
		const channels: NotificationChannel[] = []
		if (input.pushEnabled) channels.push(NotificationChannel.PUSH)
		if (input.emailEnabled) channels.push(NotificationChannel.EMAIL)
		if (channels.length === 0) {
			throw new BaseError<NotificationsDomainErrors>('NO_CHANNEL_ENABLED')
		}

		return this.withTransaction(tx, async tx => {
			const notification = BkdashNotification.create({
				title: input.title,
				content: input.content,
				category: input.category as NotificationCategory,
				origin: NotificationOrigin.ADMIN,
				important: input.important,
				contentType: input.contentType,
				payload: input.payload,
				storeId: input.storeId ?? null,
			})
			await this.notifications.save(notification, tx)

			let deliveriesCreated = 0
			for (const recipient of targets) {
				for (const channel of channels) {
					const delivery = BkdashNotificationDelivery.create({
						notificationId: notification.id.value,
						userId: recipient,
						channel,
					})
					await this.deliveries.save(delivery, tx)
					deliveriesCreated++
				}
			}

			await this.domainEventRepository.save(
				new NotificationSentEvent({
					entityId: notification.id.value,
					ownerId: input.storeId ?? input.userId,
					payload: {
						notificationId: notification.id.value,
						storeId: input.storeId ?? null,
						category: input.category,
						channels,
						recipientCount: targets.length,
						deliveriesCreated,
					},
				}),
				tx,
			)

			return {
				notificationId: notification.id.value,
				deliveriesCreated,
				deliveriesSkippedDuplicate: 0,
			}
		})
	}
}

// Internal handlers for billing-emitted domain events.
//
// Webhook ingest chain (SPEC-13): raw received → mapper → intermediate →
// domain transition. ExternalSubscriptionUpdatedHandler owns the write side: it
// loads/creates the Subscription aggregate, calls the imperative domain method
// (create / markPaid / markRenewed / cancel / markOverdue), and persists the
// aggregate + the domain event in one transaction. The saved domain events ride
// the outbox to the side-effect handlers below — which do effects only, never
// persistence.
export { BillingWebhookReceivedHandler } from './BillingWebhookReceivedHandler'
export { ExternalSubscriptionUpdatedHandler } from './ExternalSubscriptionUpdatedHandler'

// SubscriptionPaused is not a webhook transition (no ExternalSubscriptionUpdated
// 'paused'); its persist handler stays the write side for whatever raises it.
export { SubscriptionPausedHandler } from './SubscriptionPausedHandler'

// Cross-BC bridges: turn state-change domain events into the
// integration.shared.subscription.quota_updated event Tenancy consumes for
// quota-cache invalidation. Mediator allows multiple handlers per event name.
export {
	SubscriptionCreatedQuotaUpdatedHandler,
	SubscriptionCancelledQuotaUpdatedHandler,
	SubscriptionPausedQuotaUpdatedHandler,
	SubscriptionOverdueQuotaUpdatedHandler,
} from './SubscriptionQuotaUpdatedPublisher'

// External handlers (subscribers to integration events from other BCs /
// the Go worker) that fan out notifications.
//
// IntegrationHandshakeFailedNotifyHandler: pushes
// INTEGRATION_DISCONNECTED to the StoreIntegration owner when Go
// reports a credential handshake failure.
//
// OrderUpdatedNotifyHandler: pushes ORDER_RECEIVED to every store member
// on `isNew=true` order events from Go. Store-level opt-in toggle
// is a future iter.
//
// DEFERRED (iter 272 audit closure):
//   - OnStoreMemberInvited → requires a UserQueryService.findByEmail
//     port (P1-IDENTITY hasn't shipped); invitee may not have an
//     account yet, so the lookup is non-trivial. Also: email
//     transport itself is out of notifications BC scope.
//   - OnFcmTokenRegistered → needs a routing-table service; no such
//     service exists today. Land it paired with the routing service.
//   - OnUserPreferencesUpdated → same routing-table dependency.
export { IntegrationHandshakeFailedNotifyHandler } from './IntegrationHandshakeFailedNotifyHandler'
export { OrderUpdatedNotifyHandler } from './OrderUpdatedNotifyHandler'

