export interface MailMessage {
	to: string
	subject: string
	body: string
}

export abstract class MailSender {
	abstract sendMail(message: MailMessage): Promise<void>
}

import * as aws from "@aws-sdk/client-ses";
import { Injectable, InternalServerErrorException } from "@nestjs/common";
import { ConfigService } from "@nestjs/config";
import { TraceClass } from "@utils/tracing";
import { createTransport } from "nodemailer";
import { EmailTemplate } from "./templates/emailTemplate";

@Injectable()
@TraceClass()
export class EmailSenderService {
	constructor(private readonly configService: ConfigService) {}

	async sendEmail(to: string, email: EmailTemplate): Promise<void> {
		const ses = new aws.SES();

		const transport = createTransport({ SES: { aws, ses } });
		const { subject } = email;
		const html = await email.getBody();

		try {
			await transport.sendMail({
				from: this.configService.get<string>("AWS_SES_SOURCE"),
				html,
				subject,
				to,
			});
		} catch (error) {
			console.error("[EmailSenderService] Failed to send email:", error);
			throw new InternalServerErrorException("Failed to send email.");
		}
	}

	async sendRawHtml(to: string, subject: string, html: string): Promise<void> {
		const ses = new aws.SES();
		const transport = createTransport({ SES: { aws, ses } });

		try {
			await transport.sendMail({
				from: this.configService.get<string>("AWS_SES_SOURCE"),
				html,
				subject,
				to,
			});
		} catch (error) {
			console.error("[EmailSenderService] Failed to send email:", error);
		}
	}
}

import { render } from '@react-email/render'
import InlineCss from 'inline-css'
import { ReactNode } from 'react'

export abstract class EmailTemplate {
	protected abstract get body(): ReactNode
	abstract readonly subject: string

	async getBody(): Promise<string> {
		const content = await render(this.body)

		return InlineCss(content, { url: ' ' })
	}
}

import { injectable } from 'tsyringe-neo'
import { MailMessage, MailSender } from './MailSender'

@injectable()
export class ConsoleMailSender extends MailSender {
	async sendMail(message: MailMessage): Promise<void> {
		console.info('[MailSender]', {
			to: message.to,
			subject: message.subject,
			body: message.body,
		})
	}
}

import { describe, it, expect } from 'bun:test'
import { renderResetPasswordEmail, renderAccountCreatedEmail } from './index'

describe('auth email templates', () => {
	it('reset password email contains the name and the reset url', async () => {
		const msg = await renderResetPasswordEmail({ name: 'Alice', url: 'http://localhost:5173/reset-password?token=abc123' })
		expect(msg.subject.length).toBeGreaterThan(0)
		expect(msg.body).toContain('Alice')
		expect(msg.body).toContain('http://localhost:5173/reset-password?token=abc123')
	})

	it('account-created email contains the name', async () => {
		const msg = await renderAccountCreatedEmail({ name: 'Bob' })
		expect(msg.subject.length).toBeGreaterThan(0)
		expect(msg.body).toContain('Bob')
	})
})

