import { injectable } from 'tsyringe-neo'
import { EventHandler } from '@bk-dash/core-typescript'
import { SubscriptionPausedEvent } from '../events'
import { SubscriptionRepository } from '../repositories/SubscriptionRepository'

@injectable()
export class SubscriptionPausedHandler extends EventHandler<typeof SubscriptionPausedEvent> {
	readonly event = SubscriptionPausedEvent

	constructor(private readonly subscriptions: SubscriptionRepository) {
		super()
	}

	async handle(event: this['input']): Promise<this['output']> {
		const subscription = await this.subscriptions.findByPlatformAndExternalId(event.payload.platform, event.payload.externalId)
		if (!subscription) return

		subscription.pause()
		await this.subscriptions.save(subscription)
	}
}

import { Auth, Public, UserOnly } from "@decorators";
import { CreateUser, RecoverPassword, UserRepository } from "@modules/users";
import { NewSubscriptionEmail } from "@modules/users/emails/NewSubscriptionEmail";
import {
	BadRequestException,
	Body,
	Controller,
	Get,
	Headers,
	Param,
	ParseUUIDPipe,
	Post,
	Query,
	UnauthorizedException,
} from "@nestjs/common";
import { ApiCookieAuth, ApiOperation, ApiResponse, ApiTags } from "@nestjs/swagger";
import { MailProvider } from "@shared/providers/mail";
import { AuthData } from "@shared/types";
import { Subscription } from "sql";
import { GetSubscriptionDto } from "./dto/getSubscription.dto";
import { SubscriptionCreatedEmail, SubscriptionRenewalConfirmedEmail } from "./emails";
import { SubscriptionCancelledEmail } from "./emails/SubscriptionCancelledEmail";
import { SubscriptionRenewedEmail } from "./emails/SubscriptionRenewedEmail";
import { SubscriptionService } from "./subscription.service";

@ApiTags("Subscriptions")
@Controller("subscriptions")
export class SubscriptionController {
	constructor(
		private readonly createUser: CreateUser,
		private readonly mailProvider: MailProvider,
		readonly _recoverPassword: RecoverPassword,
		private readonly subscriptionService: SubscriptionService,
		private readonly userRepository: UserRepository,
	) {}

	@ApiOperation({
		description:
			"Retrieve all active subscriptions for the authenticated user, including plan details, expiration dates, and payment status.",
		summary: "Get User Subscriptions",
	})
	@ApiCookieAuth()
	@ApiResponse({
		description: "User subscriptions retrieved successfully",
		status: 200,
		type: [GetSubscriptionDto],
	})
	@ApiResponse({
		description: "Unauthorized - Invalid or missing authentication token",
		status: 401,
	})
	@UserOnly()
	@Get()
	async getUserSubscriptions(@Auth() { userId }: AuthData): Promise<{
		subscriptions: Partial<Subscription>[];
	}> {
		const subscriptions = await this.subscriptionService.getUserSubscriptions(userId);
		return { subscriptions };
	}

	@ApiResponse({ description: "Ok.", status: 200, type: GetSubscriptionDto })
	@ApiResponse({ description: "Não autorizado.", status: 401 })
	@ApiResponse({ description: "Assinatura não encontrada.", status: 404 })
	@UserOnly()
	@Get(":subscriptionId")
	async getSubscription(
		@Auth() { userId }: AuthData,
		@Param("subscriptionId", new ParseUUIDPipe({ version: "4" }))
		subscriptionId: string,
	): Promise<Partial<Subscription>> {
		return this.subscriptionService.getSubscriptionById(subscriptionId, userId);
	}

	@ApiResponse({
		description: "Subscription added.",
		status: 200,
		type: GetSubscriptionDto,
	})
	@ApiResponse({ description: "Não autorizado.", status: 401 })
	@ApiResponse({ description: "Assinatura não encontrada.", status: 404 })
	@Public()
	@Post()
	async create(
		@Query("host") host: string,
		@Body() data: Record<string, any>,
		@Headers() headers: Record<string, any>,
	): Promise<Partial<Subscription> | { message: string }> {
		const platformMapper = this.subscriptionService.getPlatformMapper(host);

		if (!platformMapper) {
			throw new UnauthorizedException("Chamada de API não autorizada.");
		}

		let {
			email,
			externalSubscriptionId,
			name,
			orderId,
			phone,
			planType,
			planTier,
			userId,
			subscriptionId,
			isRenew,
		} = await platformMapper.getSubscriptionDetails({ ...data, ...headers });

		if (subscriptionId) {
			const currentSubscription = await this.subscriptionService.getSubscriptionById(subscriptionId);

			if (!currentSubscription) {
				throw new BadRequestException("Assinatura informada não encontrada.");
			}

			if (currentSubscription.planTier !== planTier || currentSubscription.planType !== planType) {
				throw new BadRequestException("Tiers ou tipos de assinatura diferentes.");
			}

			if (currentSubscription.active) {
				return { message: "Assinatura já alterada." };
			}

			if (!isRenew) {
				await this.subscriptionService.changeExternalSubscription({
					externalSubscriptionId,
					paymentId: orderId,
					platform: platformMapper.platform,
					subscriptionId,
				});
			} else {
				await this.subscriptionService.renewSubscription({
					externalSubscriptionId,
					id: subscriptionId,
					paymentId: orderId,
				});
			}

			await this.mailProvider.sendEmail(
				email,
				new SubscriptionRenewalConfirmedEmail({
					name,
					subscriptionId: externalSubscriptionId,
				}),
			);

			return { message: "Assinatura alterada e renovada." };
		}

		if (!userId) {
			const user = await this.userRepository.findByEmail(email, ["id"]);
			userId = user?.id ?? null;
		}

		const existedBefore =
			!!(await this.subscriptionService.getSubscriptionByExternalId(externalSubscriptionId));

		const subscriptionResult = await this.subscriptionService.create(userId, {
			id: externalSubscriptionId,
			paymentId: orderId,
			planTier,
			planType,
			platform: platformMapper.platform,
		});

		if (!userId) {
			await this.createUser.execute({
				email,
				name,
				password: `${email}123@`,
				phoneNumber: phone,
				subscriptionId: subscriptionResult.id!,
			});

			await this.mailProvider.sendEmail(email, new SubscriptionCreatedEmail({ email, name }));

			return { message: "Subscription created" };
		}

		if (!existedBefore) {
			await this.mailProvider.sendEmail(
				email,
				new NewSubscriptionEmail({
					name,
				}),
			);

			return { message: "Subscription created" };
		}

		await this.mailProvider.sendEmail(
			email,
			new SubscriptionRenewedEmail({
				name,
				subscriptionId: externalSubscriptionId,
			}),
		);

		return { message: "Subscription renewed" };
	}

	@ApiResponse({
		description: "Subscription cancelled.",
		status: 200,
		type: GetSubscriptionDto,
	})
	@ApiResponse({ description: "Não autorizado.", status: 401 })
	@ApiResponse({ description: "Assinatura não encontrada.", status: 404 })
	@Public()
	@Post("cancel")
	async cancel(
		@Query("host") host: string,
		@Body() data: Record<string, any>,
	): Promise<Partial<Subscription> | { message: string }> {
		const platformMapper = this.subscriptionService.getPlatformMapper(host);

		if (!platformMapper) {
			throw new UnauthorizedException("Chamada de API não autorizada.");
		}

		const { email, externalSubscriptionId } = await platformMapper.getSubscriptionDetails(data);

		if (!externalSubscriptionId) {
			throw new BadRequestException("Subscription ID is required");
		}

		await this.subscriptionService.cancelSubscription(externalSubscriptionId);

		await this.mailProvider.sendEmail(email, new SubscriptionCancelledEmail());

		return { message: "Subscription cancelled" };
	}
}

import { injectable } from 'tsyringe-neo'
import { EventHandler, ExternalMediator } from '@bk-dash/core-typescript'
import { SubscriptionQuotaUpdatedEvent } from '@bk-dash/contracts-typescript/wire/events'
import type { PlanTier } from '@bk-dash/contracts-typescript/wire/enums'
import { SubscriptionCancelledEvent, SubscriptionCreatedEvent, SubscriptionOverdueEvent, SubscriptionPausedEvent } from '../events'

/**
 * Internal-to-billing handlers that bridge state-change domain events to the
 * `integration.shared.subscription.quota_updated` integration event the
 * Tenancy BC consumes for quota-cache invalidation.
 *
 * Wired for the 4 events that change effective quota: Created (newly
 * active), Cancelled + Paused + Overdue (active rights revoked). Paid and
 * Renewed don't change effective quota — same tier remains active, no
 * publish.
 *
 * One handler class per event because EventHandler.name binds to
 * `this.event.name` for framework auto-registration — the mediator allows
 * multiple handlers per event name, but a single class can only declare one
 * `event` field.
 */

async function publish(mediator: ExternalMediator, userId: string, tier: PlanTier): Promise<void> {
	await mediator.publish(
		new SubscriptionQuotaUpdatedEvent({
			ownerId: userId,
			payload: { userId, tier },
		}),
	)
}

/** Newly active subscription → quota refresh. */
@injectable()
export class SubscriptionCreatedQuotaUpdatedHandler extends EventHandler<typeof SubscriptionCreatedEvent> {
	readonly event = SubscriptionCreatedEvent

	constructor(private readonly mediator: ExternalMediator) {
		super()
	}

	async handle(event: this['input']): Promise<void> {
		await publish(this.mediator, event.payload.userId, event.payload.tier)
	}
}

/** Cancellation → quota downgrade. */
@injectable()
export class SubscriptionCancelledQuotaUpdatedHandler extends EventHandler<typeof SubscriptionCancelledEvent> {
	readonly event = SubscriptionCancelledEvent

	constructor(private readonly mediator: ExternalMediator) {
		super()
	}

	async handle(event: this['input']): Promise<void> {
		// SubscriptionCancelledEvent's payload doesn't carry userId (lean spec);
		// the canonical actor is on event.ownerId (mapper sets it from
		// existing.userId when the cancellation is mapped). Defensive '' fallback.
		const userId = event.ownerId ?? ''
		await publish(this.mediator, userId, event.payload.tier)
	}
}

/** Pause → quota effectively reduced (active row but no service rights). */
@injectable()
export class SubscriptionPausedQuotaUpdatedHandler extends EventHandler<typeof SubscriptionPausedEvent> {
	readonly event = SubscriptionPausedEvent

	constructor(private readonly mediator: ExternalMediator) {
		super()
	}

	async handle(event: this['input']): Promise<void> {
		const userId = event.ownerId ?? ''
		await publish(this.mediator, userId, event.payload.tier)
	}
}

/** Overdue → quota effectively reduced (payment late, active rights revoked). */
@injectable()
export class SubscriptionOverdueQuotaUpdatedHandler extends EventHandler<typeof SubscriptionOverdueEvent> {
	readonly event = SubscriptionOverdueEvent

	constructor(private readonly mediator: ExternalMediator) {
		super()
	}

	async handle(event: this['input']): Promise<void> {
		const userId = event.ownerId ?? ''
		await publish(this.mediator, userId, event.payload.tier)
	}
}

import './errors' // Side-effect: registers context error codes with the framework runtime registry.
import type { InstanceRegistry } from '@bk-dash/core-typescript'
import { SubscriptionRepository, DrizzleSubscriptionRepository, MockSubscriptionRepository } from './repositories/SubscriptionRepository'
import { KiwifyWebhookVerifier } from './services/KiwifyWebhookVerifier'
import { BillingSubscriptionQueryService } from './services/BillingSubscriptionQueryService'
import { SubscriptionQueryService } from '../tenancy/services/SubscriptionQueryService'
import { StoreQueryService, MockStoreQueryService } from './services/StoreQueryService'

// KiwifyWebhookVerifier takes a `string | undefined` constructor param
// (the HMAC secret) — tsyringe can't auto-resolve `string`, so we register
// via useFactory. The factory pulls from Config; tests bypass DI and `new`
// the class directly with the test secret.
const verifierFactory = (): KiwifyWebhookVerifier => new KiwifyWebhookVerifier()

export const INSTANCE_REGISTRY: InstanceRegistry = {
	mock: [
		{ token: SubscriptionRepository, instance: MockSubscriptionRepository },
		{ token: KiwifyWebhookVerifier, useFactory: verifierFactory },
		{ token: StoreQueryService, instance: MockStoreQueryService },
	],
	integration: [
		{ token: SubscriptionRepository, instance: DrizzleSubscriptionRepository },
		{ token: KiwifyWebhookVerifier, useFactory: verifierFactory },
		// Overrides tenancy's MockSubscriptionQueryService via load order
		// (tenancy registers first; billing's later entry wins).
		{ token: SubscriptionQueryService, instance: BillingSubscriptionQueryService },
	],
	real: [
		{ token: SubscriptionRepository, instance: DrizzleSubscriptionRepository },
		{ token: KiwifyWebhookVerifier, useFactory: verifierFactory },
		{ token: SubscriptionQueryService, instance: BillingSubscriptionQueryService },
	],
}

import * as aws from "@aws-sdk/client-ses";
import { Injectable, InternalServerErrorException } from "@nestjs/common";
import { TraceClass } from "@utils/tracing";
import { createTransport } from "nodemailer";
import { BaseEmail } from "./BaseEmail";

@Injectable()
@TraceClass()
export class MailProvider {
	private readonly transport = createTransport({
		SES: {
			aws,
			ses: new aws.SES(),
		},
	});

	async sendEmail(to: string, email: BaseEmail): Promise<void> {
		const { subject } = email;
		const html = await email.getBody();

		try {
			await this.transport.sendMail({
				from: process.env.AWS_SES_SOURCE,
				html,
				subject,
				to,
			});
		} catch (error) {
			console.error("[MailProvider] Failed to send email:", error);

			throw new InternalServerErrorException("Failed to send email.");
		}
	}
}

