import { PrismaService } from "@infra";
import { InternalPlatformMapper } from "@modules/webhooks/mappers/platform/internal";
import { ShopifyPlatformMapper } from "@modules/webhooks/mappers/platform/shopify";
import { BadRequestException, ConflictException, Injectable, NotFoundException } from "@nestjs/common";
import { PlanType } from "@shared/types";
import { TraceClass } from "@utils/tracing";
import { addMonths, isAfter } from "date-fns";
import { Subscription } from "sql";
import { PlatformMapper } from "../webhooks/mappers/platform";
import { KiwifyPlatformMapper } from "../webhooks/mappers/platform/kiwify";
import { ChangeExternalSubscriptionDto } from "./dto/changeExternalSubscription.dto";
import { CreateSubscriptionDto } from "./dto/createSubscription.dto";
import { UpdateSubscriptionDto } from "./dto/updateSubscription.dto";

@Injectable()
@TraceClass()
export class SubscriptionService {
	constructor(private readonly prismaService: PrismaService) {}

	async create(
		userId: string | null,
		createSubscriptionDto: CreateSubscriptionDto,
	): Promise<Partial<Subscription>> {
		return this.prismaService.subscription.upsert({
			create: {
				active: true,
				expirationDate: this.getExpirationDateFromPlan(createSubscriptionDto.planType),
				externalId: createSubscriptionDto.id,
				payments: {
					create: {
						externalId: createSubscriptionDto.paymentId,
						paymentDate: new Date(),
						planType: createSubscriptionDto.planType,
					},
				},
				planTier: createSubscriptionDto.planTier,
				planType: createSubscriptionDto.planType,
				platform: createSubscriptionDto.platform,
				renew: true,
				userId,
			},
			select: {
				active: true,
				expirationDate: true,
				externalId: true,
				id: true,
				planType: true,
				platform: true,
				renew: true,
			},
			update: {
				active: true,
			},
			where: {
				externalId: createSubscriptionDto.id,
			},
		});
	}

	async renewSubscription(updateSubscriptionDto: UpdateSubscriptionDto): Promise<Partial<Subscription>> {
		const subscription = await this.getSubscriptionByExternalId(updateSubscriptionDto.id);

		if (!subscription) {
			throw new NotFoundException("Assinatura não encontrada.");
		}

		if (isAfter(subscription.expirationDate!, new Date())) {
			throw new ConflictException("Assinatura não pode ser renovada antes da expiração");
		}

		return this.prismaService.subscription.update({
			data: {
				active: true,
				expirationDate: this.getExpirationDateFromPlan(PlanType[subscription.planType!]),
				externalId: updateSubscriptionDto.externalSubscriptionId,
				payments: {
					create: {
						externalId: updateSubscriptionDto.paymentId,
						paymentDate: new Date(),
						planType: PlanType[subscription.planType!],
					},
				},
				renew: true,
			},
			select: {
				active: true,
