import { beforeEach, describe, expect, it } from 'bun:test'
import { BillingPlatform, PlanPeriod, PlanTier } from '@bk-dash/contracts-typescript/wire/enums'
import { testId } from '@test/support'
import { Subscription } from '../entities/Subscription'
import { SubscriptionPausedEvent } from '../events'
import { MockSubscriptionRepository } from '../repositories/SubscriptionRepository/MockSubscriptionRepository'
import { SubscriptionPausedHandler } from './SubscriptionPausedHandler'

const USER_ID = testId('user', '1')
const EXTERNAL_ID = 'kiwify_sub_002'

function makeActiveSubscription(): Subscription {
	return Subscription.create({
		userId: USER_ID,
		platform: BillingPlatform.KIWIFY,
		externalSubscriptionId: EXTERNAL_ID,
		tier: PlanTier.INTERMEDIATE,
		period: PlanPeriod.MONTHLY,
		occurredAt: new Date('2026-05-01T00:00:00.000Z'),
	})
}

function makeEvent(): SubscriptionPausedEvent {
	return new SubscriptionPausedEvent({
		entityId: EXTERNAL_ID,
		ownerId: USER_ID,
		payload: {
			externalId: EXTERNAL_ID,
			platform: BillingPlatform.KIWIFY,
			tier: PlanTier.INTERMEDIATE,
		},
	}) as SubscriptionPausedEvent
}

describe('SubscriptionPausedHandler', () => {
	let repo: MockSubscriptionRepository
	let handler: SubscriptionPausedHandler

	beforeEach(() => {
		repo = new MockSubscriptionRepository()
		handler = new SubscriptionPausedHandler(repo)
	})

	it('flips isActive=false on pause()', async () => {
		const sub = makeActiveSubscription()
		repo.seed(sub)

		await handler.handle(makeEvent() as any)

		const found = await repo.findByPlatformAndExternalId(BillingPlatform.KIWIFY, EXTERNAL_ID)
		expect(found?.isActive).toBe(false)
	})

	it('exits silently when no matching subscription exists', async () => {
		await handler.handle(makeEvent() as any)
		const found = await repo.findByPlatformAndExternalId(BillingPlatform.KIWIFY, EXTERNAL_ID)
		expect(found).toBeUndefined()
	})
})

