import { Repository } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import type { BillingPlatform } from '@bk-dash/contracts-typescript/wire/enums'
import { Subscription } from '../../entities/Subscription'

// The port speaks `Transaction` (the persistence-agnostic handle from the
// UnitOfWork), never `DrizzleClient` — Drizzle is an infra detail that only the
// Drizzle implementation is allowed to know about (and cast to).
export abstract class SubscriptionRepository extends Repository<Subscription> {
	abstract findById(id: string, tx?: Transaction): Promise<Subscription | undefined>

	// Each user has at most one active subscription — the `(platform,
	// external_subscription_id)` unique index enforces provider-side
	// uniqueness, but T38 GetMySubscription wants the user-side lookup.
	abstract findByUserId(userId: string, tx?: Transaction): Promise<Subscription | undefined>

	// All active subscriptions for a user (a user may hold several — paid +
	// internal grants, or multiple grants). Drives GetMySubscriptions.
	abstract findActiveByUserId(userId: string, tx?: Transaction): Promise<Subscription[]>

	// Webhook idempotency + post-hoc orphan-event resolution: the canonical
	// (platform, externalSubscriptionId) lookup HandleBillingWebhook (C56) uses
	// to decide create-vs-update before applyEvent runs.
	abstract findByPlatformAndExternalId(
		platform: BillingPlatform,
		externalSubscriptionId: string,
		tx?: Transaction,
	): Promise<Subscription | undefined>
}

