import { injectable } from 'tsyringe-neo'
import { EventHandler, MailSender } from '@bk-dash/core-typescript'
import { UserDirectoryService } from '../../tenancy/services/UserDirectoryService'
import { SubscriptionCreatedEvent } from '../events'
import { renderSubscriptionCreatedEmail } from '../services/MailSender'

/**
 * Transactional email side-effect for a new subscription. Reacts to the
 * SubscriptionCreated domain event off the outbox; the recipient address +
 * display name are resolved through the cross-BC UserDirectoryService (auth
 * owns the canonical users table). Created carries `userId` in its payload, so
 * no subscription lookup is needed. Non-persisting — pure effect.
 */
@injectable()
export class SubscriptionCreatedEmailHandler extends EventHandler<typeof SubscriptionCreatedEvent> {
	readonly event = SubscriptionCreatedEvent

	constructor(
		private readonly users: UserDirectoryService,
		private readonly mailSender: MailSender,
	) {
		super()
	}

	async handle(event: this['input']): Promise<this['output']> {
		const [recipient] = await this.users.getMany([event.payload.userId])
		if (!recipient) return

		const { subject, body } = await renderSubscriptionCreatedEmail({ name: recipient.name ?? recipient.email })
		await this.mailSender.sendMail({ to: recipient.email, subject, body })
	}
}

