/**
 * Transactional email side-effect for a recurring charge. The renewed event is
 * lean (no userId) — the subscription row already exists, so the recipient is
 * resolved by loading it via (platform, externalId) and looking the user up in
 * the cross-BC UserDirectoryService. Non-persisting — pure effect.
 */
@injectable()
export class SubscriptionRenewedEmailHandler extends EventHandler<typeof SubscriptionRenewedEvent> {
	readonly event = SubscriptionRenewedEvent

	constructor(
		private readonly subscriptions: SubscriptionRepository,
		private readonly users: UserDirectoryService,
		private readonly mailSender: MailSender,
	) {
		super()
	}

	async handle(event: this['input']): Promise<this['output']> {
		const subscription = await this.subscriptions.findByPlatformAndExternalId(event.payload.platform, event.payload.externalId)
		if (!subscription) return

		const [recipient] = await this.users.getMany([subscription.userId.value])
		if (!recipient) return

		const { subject, body } = await renderSubscriptionRenewedEmail({ name: recipient.name ?? recipient.email })
		await this.mailSender.sendMail({ to: recipient.email, subject, body })
	}
}

