// Recipe: dev:packages/api/src/auth/entities/User.ts
// phone is a nullable Phone value object — required at sign-up (better-auth +
// SignUp contract), but nullable here so legacy users without a phone hydrate.
import { AggregateRoot } from '@bk-dash/core-typescript'
import { z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { Phone } from '@shared/objects'

const UserSchema = z.object({
	name: z.string().nullable().optional(),
	email: z.email(),
	emailVerified: z.boolean().optional().default(false),
	phone: z.instance(Phone).nullable().optional(),
	image: z.string().nullable().optional(),
})

export type UserProps = Z.infer<typeof UserSchema>

export class User extends AggregateRoot<typeof UserSchema> {
	static override schema = UserSchema

	static create(data: { name?: string | null; email: string; emailVerified?: boolean; phone?: Phone | null; image?: string | null }): User {
		return new User({
			name: data.name ?? null,
			email: data.email,
			emailVerified: data.emailVerified ?? false,
			phone: data.phone ?? null,
			image: data.image ?? null,
		})
	}
}

export interface User extends UserProps {}
