import { injectable } from 'tsyringe-neo'
import { EventHandler, MailSender } from '@bk-dash/core-typescript'
import { UserRepository } from '../../auth/repositories/UserRepository'
import { SubscriptionCreatedEvent } from '../events'
import { renderSubscriptionCreatedEmail } from '../services/MailSender'

/**
 * Reacts to the SubscriptionCreated domain event off the outbox and notifies
 * the subscriber that their plan is active. Created carries `userId` in its
 * payload, so the User entity is loaded directly from auth's UserRepository
 * (cross-context repository read) for the recipient address + name.
 * Non-persisting — pure effect.
 */
@injectable()
export class SubscriptionCreatedHandler extends EventHandler<typeof SubscriptionCreatedEvent> {
	readonly event = SubscriptionCreatedEvent

	constructor(
		private readonly users: UserRepository,
		private readonly mailSender: MailSender,
	) {
		super()
	}

	async handle(event: this['input']): Promise<this['output']> {
		const user = await this.users.findById(event.payload.userId)
		if (!user) return

		const { subject, body } = await renderSubscriptionCreatedEmail({ name: user.name ?? user.email })
		await this.mailSender.sendMail({ to: user.email, subject, body })
	}
}

