/**
 * Reacts to the SubscriptionRenewed domain event and notifies the subscriber
 * that their recurring charge went through. The renewed event is lean (no
 * userId) — the subscription row already exists, so it's loaded by (platform,
 * externalId) and the User entity is read from auth's UserRepository for the
 * recipient. Non-persisting — pure effect.
 */
@injectable()
export class SubscriptionRenewedHandler extends EventHandler<typeof SubscriptionRenewedEvent> {
	readonly event = SubscriptionRenewedEvent

	constructor(
		private readonly subscriptions: SubscriptionRepository,
		private readonly users: UserRepository,
		private readonly mailSender: MailSender,
	) {
		super()
	}

	async handle(event: this['input']): Promise<this['output']> {
		const subscription = await this.subscriptions.findByPlatformAndExternalId(event.payload.platform, event.payload.externalId)
		if (!subscription) return

		const user = await this.users.findById(subscription.userId.value)
		if (!user) return

		const { subject, body } = await renderSubscriptionRenewedEmail({ name: user.name ?? user.email })
		await this.mailSender.sendMail({ to: user.email, subject, body })
	}
}

