import { UserRepository } from '../../auth/repositories/UserRepository'
import { SubscriptionCancelledEvent } from '../events'
import { SubscriptionRepository } from '../repositories/SubscriptionRepository'
import { renderSubscriptionCancelledEmail } from '../services/MailSender'

/**
 * Reacts to the SubscriptionCancelled domain event and confirms to the
 * subscriber that no further charges will be made. The cancelled event is lean
 * (no userId) — the subscription row still exists (isActive=false), so it's
 * loaded by (platform, externalId) and the User entity is read from auth's
 * UserRepository for the recipient. Non-persisting — pure effect.
 */
@injectable()
export class SubscriptionCancelledHandler extends EventHandler<typeof SubscriptionCancelledEvent> {
	readonly event = SubscriptionCancelledEvent

	constructor(
		private readonly subscriptions: SubscriptionRepository,
		private readonly users: UserRepository,
		private readonly mailSender: MailSender,
	) {
		super()
	}

	async handle(event: this['input']): Promise<this['output']> {
		const subscription = await this.subscriptions.findByPlatformAndExternalId(event.payload.platform, event.payload.externalId)
		if (!subscription) return

		const user = await this.users.findById(subscription.userId.value)
		if (!user) return

		const { subject, body } = await renderSubscriptionCancelledEmail({ name: user.name ?? user.email })
		await this.mailSender.sendMail({ to: user.email, subject, body })
	}
}

