// template and send via MailSender. They share the created/renewed/cancelled
// event names with the quota publishers above (mediator fans out to both).
// The recipient address + name come from the cross-BC UserDirectoryService.
export { SubscriptionCreatedEmailHandler } from './SubscriptionCreatedEmailHandler'
