import { beforeEach, describe, expect, it } from 'bun:test'
import { BillingPlatform, PlanPeriod, PlanTier } from '@bk-dash/contracts-typescript/wire/enums'
import { type MailMessage, MailSender } from '@bk-dash/core-typescript'
import { User } from '../../auth/entities/User'
import { MockUserRepository } from '../../auth/repositories/UserRepository/MockUserRepository'
import { Subscription } from '../entities/Subscription'
import { SubscriptionCancelledEvent, SubscriptionCreatedEvent, SubscriptionRenewedEvent } from '../events'
import { MockSubscriptionRepository } from '../repositories/SubscriptionRepository/MockSubscriptionRepository'
import { SubscriptionCancelledHandler } from './SubscriptionCancelledHandler'
import { SubscriptionCreatedHandler } from './SubscriptionCreatedHandler'
import { SubscriptionRenewedHandler } from './SubscriptionRenewedHandler'

const EXTERNAL_ID = 'kiwify_sub_notify_1'

class CapturingMailSender extends MailSender {
	readonly sent: MailMessage[] = []
	async sendMail(message: MailMessage): Promise<void> {
		this.sent.push(message)
	}
}

function makeUser(): User {
	return User.create({ name: 'Alice', email: 'alice@example.com' })
}

function makeSubscriptionFor(userId: string): Subscription {
	return Subscription.create({
		userId,
		platform: BillingPlatform.KIWIFY,
		externalSubscriptionId: EXTERNAL_ID,
		tier: PlanTier.INTERMEDIATE,
		period: PlanPeriod.MONTHLY,
		occurredAt: new Date('2026-05-01T00:00:00.000Z'),
	})
}

describe('subscription transactional notification handlers', () => {
	let subs: MockSubscriptionRepository
	let usersRepo: MockUserRepository
	let mail: CapturingMailSender
	let user: User

	beforeEach(() => {
		subs = new MockSubscriptionRepository()
		usersRepo = new MockUserRepository()
		mail = new CapturingMailSender()
		user = makeUser()
		usersRepo.seed(user)
	})

	it('created → loads the user by payload.userId and emails them', async () => {
		const handler = new SubscriptionCreatedHandler(usersRepo, mail)
		const event = new SubscriptionCreatedEvent({
			entityId: EXTERNAL_ID,
			ownerId: user.id.value,
			payload: {
				externalId: EXTERNAL_ID,
				platform: BillingPlatform.KIWIFY,
				tier: PlanTier.INTERMEDIATE,
				userId: user.id.value,
				period: PlanPeriod.MONTHLY,
			},
		})

		await handler.handle(event as any)

		expect(mail.sent).toHaveLength(1)
		expect(mail.sent[0]?.to).toBe('alice@example.com')
		expect(mail.sent[0]?.subject).toContain('criada')
		expect(mail.sent[0]?.body).toContain('Alice')
	})

	it('renewed → resolves the user via the seeded subscription', async () => {
		subs.seed(makeSubscriptionFor(user.id.value))
		const handler = new SubscriptionRenewedHandler(subs, usersRepo, mail)
		const event = new SubscriptionRenewedEvent({
			entityId: EXTERNAL_ID,
			ownerId: user.id.value,
			payload: { externalId: EXTERNAL_ID, platform: BillingPlatform.KIWIFY, tier: PlanTier.INTERMEDIATE },
		})

		await handler.handle(event as any)

		expect(mail.sent).toHaveLength(1)
		expect(mail.sent[0]?.to).toBe('alice@example.com')
		expect(mail.sent[0]?.subject).toContain('renovada')
	})

	it('cancelled → resolves the user via the seeded subscription', async () => {
		subs.seed(makeSubscriptionFor(user.id.value))
		const handler = new SubscriptionCancelledHandler(subs, usersRepo, mail)
		const event = new SubscriptionCancelledEvent({
